/**
 * Generated by `createservice subscription.CancelSubscriptionRenewalService --type mutations`
 */
const { faker } = require('@faker-js/faker')
const dayjs = require('dayjs')

const { makeLoggedInAdminClient, makeClient, expectToThrowGQLError } = require('@open-condo/keystone/test.utils')
const { expectToThrowAccessDeniedErrorToResult, expectToThrowAuthenticationErrorToResult } = require('@open-condo/keystone/test.utils')

const { MANAGING_COMPANY_TYPE } = require('@condo/domains/organization/constants/common')
const { createTestOrganizationEmployeeRole, createTestOrganizationEmployee } = require('@condo/domains/organization/utils/testSchema')
const { registerNewOrganization } = require('@condo/domains/organization/utils/testSchema')
const { SUBSCRIPTION_CONTEXT_STATUS, SUBSCRIPTION_PERIOD, SUBSCRIPTION_PLAN_TYPE_FEATURE } = require('@condo/domains/subscription/constants')
const { ERRORS } = require('@condo/domains/subscription/schema/CancelSubscriptionRenewalService')
const {
    SubscriptionContext,
    createTestSubscriptionContext,
    createTestSubscriptionPlan,
    createTestSubscriptionPlanPricingRule,
    updateTestSubscriptionContext,
    cancelSubscriptionRenewalByTestClient,
    registerSubscriptionContextsByTestClient,
} = require('@condo/domains/subscription/utils/testSchema')
const { makeClientWithSupportUser, makeClientWithNewRegisteredAndLoggedInUser } = require('@condo/domains/user/utils/testSchema')

describe('CancelSubscriptionRenewalService', () => {
    let admin, support, user, anonymous
    let organization, subscriptionPlan, pricingRule

    const createPaidContext = async (org, extraAttrs = {}) => {
        const [subscriptionContext] = await createTestSubscriptionContext(admin, org, subscriptionPlan, {
            startAt: dayjs().format('YYYY-MM-DD'),
            endAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
            isTrial: false,
            subscriptionPlanPricingRule: { connect: { id: pricingRule.id } },
            status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
            ...extraAttrs,
        })
        return subscriptionContext
    }

    const createEmployee = async (org, canManageSubscriptions) => {
        const [role] = await createTestOrganizationEmployeeRole(admin, org, { canManageSubscriptions })
        const employee = await makeClientWithNewRegisteredAndLoggedInUser()
        await createTestOrganizationEmployee(admin, org, employee.user, role)
        return employee
    }

    beforeAll(async () => {
        admin = await makeLoggedInAdminClient()
        support = await makeClientWithSupportUser()
        anonymous = await makeClient()

        const [plan] = await createTestSubscriptionPlan(admin, {
            name: faker.commerce.productName(),
            organizationType: MANAGING_COMPANY_TYPE,
            isHidden: false,
            trialDays: 14,
        })
        subscriptionPlan = plan
        const [rule] = await createTestSubscriptionPlanPricingRule(admin, subscriptionPlan, {
            period: SUBSCRIPTION_PERIOD.MONTH,
            price: '1000.00',
            currencyCode: 'RUB',
        })
        pricingRule = rule
    })

    beforeEach(async () => {
        user = await makeClientWithNewRegisteredAndLoggedInUser()
        const [org] = await registerNewOrganization(user, { type: MANAGING_COMPANY_TYPE })
        organization = org
    })

    describe('Access', () => {
        test('admin can cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization, { bindingId: faker.datatype.uuid() })

            const [result] = await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            expect(result.subscriptionContexts).toHaveLength(1)
            expect(result.subscriptionContexts[0].id).toBe(subscriptionContext.id)
        })

        test('employee with canManageSubscriptions can cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization)
            const employee = await createEmployee(organization, true)

            const [result] = await cancelSubscriptionRenewalByTestClient(employee, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            expect(result.subscriptionContexts[0].id).toBe(subscriptionContext.id)
        })

        test('employee without canManageSubscriptions cannot cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization)
            const employee = await createEmployee(organization, false)

            await expectToThrowAccessDeniedErrorToResult(async () => {
                await cancelSubscriptionRenewalByTestClient(employee, {
                    subscriptionContexts: [{ id: subscriptionContext.id }],
                })
            })
        })

        test('employee cannot cancel renewal of another organization context', async () => {
            const employee = await createEmployee(organization, true)
            const ownContext = await createPaidContext(organization)
            const [otherOrganization] = await registerNewOrganization(await makeClientWithNewRegisteredAndLoggedInUser(), { type: MANAGING_COMPANY_TYPE })
            const foreignContext = await createPaidContext(otherOrganization)

            await expectToThrowAccessDeniedErrorToResult(async () => {
                await cancelSubscriptionRenewalByTestClient(employee, {
                    subscriptionContexts: [{ id: ownContext.id }, { id: foreignContext.id }],
                })
            })
        })

        test('support can cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization)

            const [result] = await cancelSubscriptionRenewalByTestClient(support, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            expect(result.subscriptionContexts[0].id).toBe(subscriptionContext.id)
        })

        test('user without employment cannot cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization)
            const regularUser = await makeClientWithNewRegisteredAndLoggedInUser()

            await expectToThrowAccessDeniedErrorToResult(async () => {
                await cancelSubscriptionRenewalByTestClient(regularUser, {
                    subscriptionContexts: [{ id: subscriptionContext.id }],
                })
            })
        })

        test('anonymous cannot cancel renewal', async () => {
            const subscriptionContext = await createPaidContext(organization)

            await expectToThrowAuthenticationErrorToResult(async () => {
                await cancelSubscriptionRenewalByTestClient(anonymous, {
                    subscriptionContexts: [{ id: subscriptionContext.id }],
                })
            })
        })
    })

    describe('Validation', () => {
        test('throws error if subscription context not found', async () => {
            await expectToThrowGQLError(async () => {
                await cancelSubscriptionRenewalByTestClient(admin, {
                    subscriptionContexts: [{ id: faker.datatype.uuid() }],
                })
            }, ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, 'result')
        })

        test('throws error if subscription context is deleted', async () => {
            const subscriptionContext = await createPaidContext(organization)
            await updateTestSubscriptionContext(admin, subscriptionContext.id, { deletedAt: dayjs().toISOString() })

            await expectToThrowGQLError(async () => {
                await cancelSubscriptionRenewalByTestClient(admin, {
                    subscriptionContexts: [{ id: subscriptionContext.id }],
                })
            }, ERRORS.SUBSCRIPTION_CONTEXT_NOT_FOUND, 'result')
        })

        test('throws error if contexts belong to different organizations', async () => {
            const ownContext = await createPaidContext(organization)
            const [otherOrganization] = await registerNewOrganization(await makeClientWithNewRegisteredAndLoggedInUser(), { type: MANAGING_COMPANY_TYPE })
            const foreignContext = await createPaidContext(otherOrganization)

            await expectToThrowGQLError(async () => {
                await cancelSubscriptionRenewalByTestClient(admin, {
                    subscriptionContexts: [{ id: ownContext.id }, { id: foreignContext.id }],
                })
            }, ERRORS.SUBSCRIPTION_CONTEXTS_FROM_DIFFERENT_ORGANIZATIONS, 'result')
        })
    })

    describe('Cancellation', () => {
        test('detaches the card and records renewalCancelledAt', async () => {
            const subscriptionContext = await createPaidContext(organization, { bindingId: faker.datatype.uuid() })

            const [result] = await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            expect(result.subscriptionContexts[0].bindingId).toBeNull()
            expect(result.subscriptionContexts[0].renewalCancelledAt).not.toBeNull()
        })

        test('records renewalCancelledAt for an invoice-paid context without a card', async () => {
            const subscriptionContext = await createPaidContext(organization, { bindingId: null })

            const [result] = await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            expect(result.subscriptionContexts[0].renewalCancelledAt).not.toBeNull()
        })

        test('keeps the original date when renewal is cancelled again', async () => {
            const cancelledAt = dayjs().subtract(3, 'day').toISOString()
            const subscriptionContext = await createPaidContext(organization, { renewalCancelledAt: cancelledAt })

            await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: subscriptionContext.id }],
            })

            const updated = await SubscriptionContext.getOne(admin, { id: subscriptionContext.id })
            expect(dayjs(updated.renewalCancelledAt).isSame(cancelledAt)).toBe(true)
        })

        test('leaves the card on another active context that still uses it', async () => {
            const bindingId = faker.datatype.uuid()
            const cancelledContext = await createPaidContext(organization, { bindingId })
            const nextContext = await createPaidContext(organization, {
                startAt: dayjs().add(1, 'month').format('YYYY-MM-DD'),
                endAt: dayjs().add(2, 'month').format('YYYY-MM-DD'),
                bindingId,
            })

            await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: cancelledContext.id }],
            })

            const updatedNext = await SubscriptionContext.getOne(admin, { id: nextContext.id })
            expect(updatedNext.bindingId).toBe(bindingId)
            expect(updatedNext.renewalCancelledAt).toBeNull()
        })

        test('cancels only the given contexts of a bundle, leaving the rest renewing', async () => {
            const [featurePlan] = await createTestSubscriptionPlan(admin, {
                organizationType: MANAGING_COMPANY_TYPE,
                planType: SUBSCRIPTION_PLAN_TYPE_FEATURE,
                ai: true,
            })
            const [featureRule] = await createTestSubscriptionPlanPricingRule(admin, featurePlan, {
                period: SUBSCRIPTION_PERIOD.MONTH,
                price: '500.00',
                currencyCode: 'RUB',
            })

            const [registered] = await registerSubscriptionContextsByTestClient(admin, {
                organization: { id: organization.id },
                subscriptionPlanPricingRules: [{ id: pricingRule.id }, { id: featureRule.id }],
                paymentType: 'invoice',
                isTrial: false,
            })

            const bindingId = faker.datatype.uuid()
            for (const bundleContext of registered.subscriptionContexts) {
                await updateTestSubscriptionContext(admin, bundleContext.id, {
                    status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                    bindingId,
                })
            }

            const featureContext = registered.subscriptionContexts.find(ctx => ctx.subscriptionPlan.id === featurePlan.id)
            const serviceContext = registered.subscriptionContexts.find(ctx => ctx.subscriptionPlan.id === subscriptionPlan.id)

            await cancelSubscriptionRenewalByTestClient(admin, {
                subscriptionContexts: [{ id: featureContext.id }],
            })

            const updatedFeature = await SubscriptionContext.getOne(admin, { id: featureContext.id })
            expect(updatedFeature.bindingId).toBeNull()
            expect(updatedFeature.renewalCancelledAt).not.toBeNull()

            const updatedService = await SubscriptionContext.getOne(admin, { id: serviceContext.id })
            expect(updatedService.bindingId).toBe(bindingId)
            expect(updatedService.renewalCancelledAt).toBeNull()
        })
    })
})
